def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    total_d = 0
    my_d = 0
    for me, op in history:
        if op == 'D':
            total_d += 1
        if me == 'D':
            my_d += 1

    recent = history[-10:] if n >= 10 else history
    recent_d = 0
    for _, op in recent:
        if op == 'D':
            recent_d += 1
    recent_len = len(recent)

    opp_streak = 0
    for _, op in reversed(history):
        if op == 'D':
            opp_streak += 1
        else:
            break

    tail = history[-3:] if n >= 3 else history
    my_d_recent = 0
    for me, _ in tail:
        if me == 'D':
            my_d_recent += 1

    punished = 0
    forgiven = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'D':
                punished += 1
            else:
                forgiven += 1

    rate = total_d / n
    recent_rate = recent_d / recent_len
    chronic = (rate >= 0.55) or (recent_rate >= 0.65) or (opp_streak >= 4)

    if last_opp == 'D':
        if last_me == 'D':
            if chronic:
                return 'D'
            if opp_streak >= 3 and rate >= 0.30:
                return 'D'
            return 'C'

        if chronic:
            return 'D'
        if opp_streak == 2 and my_d_recent > 0 and rate < 0.60:
            return 'C'
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'D' and rate < 0.55:
            return 'C'
        if total_d <= 1 and recent_d <= 1 and n > 15:
            if rng.random() < 0.12:
                return 'C'
        return 'D'

    if last_me == 'D':
        if chronic:
            return 'D'
        if total_d == 0:
            return 'D'
        if punished == 0 and forgiven >= 2 and rate < 0.18 and recent_d <= 1:
            if rng.random() < 0.30:
                return 'D'
        return 'C'

    if total_d == 0 and my_d == 0 and n >= 90:
        if rng.random() < 0.25:
            return 'D'
    return 'C'
